<style lang="scss" src="./popover.scss"></style>

<script>
import { VPopover } from "v-tooltip";
import { Component, Prop, Vue } from "vue-property-decorator";
import { has } from "../../util/has";
import { PopoverPlacement, PopoverPlacementValues } from "./popover.constants";

@Component({
  components: {
    VPopover,
  },
})
export default class Popover extends Vue {
  @Prop({
    type: Boolean,
    default: true,
  })
  autoHide;

  @Prop({
    type: String,
    default: PopoverPlacement.BOTTOM_START,
    validator: has(PopoverPlacementValues),
  })
  placement;

  isOpen = false;

  openPopover() {
    this.isOpen = true;
  }

  closePopover() {
    this.isOpen = false;
  }

  handleShow() {
    this.$emit("show");
  }
}
</script>

<template>
  <div class="Popover__Container">
    <VPopover
      class="Popover__PopoverTriggerWrapper"
      popoverClass="Popover__Popover"
      popoverBaseClass="TheTooltip ThePopover"
      popoverWrapperClass="TheTooltip__Wrapper ThePopover__Wrapper"
      popoverArrowClass="TheTooltip__Arrow ThePopover__Arrow"
      popoverInnerClass="TheTooltip__Inner ThePopover__Inner"
      openClass="TheTooltip--Open ThePopover--Open"
      boundariesElement="viewport"
      trigger="manual"
      :placement="placement"
      :autoHide="autoHide"
      :open="isOpen"
      @hide="isOpen = false"
      @open="isOpen = true"
      @show="handleShow"
    >
      <slot
        name="trigger"
        :isOpen="isOpen"
        :open="openPopover"
        :close="closePopover"
      />

      <template #popover>
        <slot
          name="popover"
          :isOpen="isOpen"
          :open="openPopover"
          :close="closePopover"
        />
      </template>
    </VPopover>
  </div>
</template>
